package uz.medclinic.vendorprotocol

import java.time.Instant
import java.util.UUID

/**
 * Periodic technical health report. Must never contain patient data.
 * [heartbeatId] is generated by the client and makes retries idempotent.
 */
data class HeartbeatRequest(
    val heartbeatId: UUID,
    val sentAt: Instant,
    val appVersion: String,
    val uptimeSeconds: Long,
    val disks: List<DiskUsage> = emptyList(),
    val lastBackup: BackupInfo? = null,
    val errors: ErrorCounters? = null,
    val installedLicenseId: UUID? = null,
)

data class DiskUsage(
    val mount: String,
    val totalBytes: Long,
    val freeBytes: Long,
)

enum class BackupStatus { SUCCESS, FAILED }

data class BackupInfo(
    val completedAt: Instant,
    val status: BackupStatus,
    /** Time of the latest successful backup (equals [completedAt] when [status] is SUCCESS). */
    val lastSuccessAt: Instant? = null,
    val sizeBytes: Long? = null,
)

data class ErrorCounters(
    val since: Instant,
    val errorCount: Long,
    val warningCount: Long,
)

data class HeartbeatResponse(
    val serverTime: Instant,
    val nextHeartbeatInSeconds: Int,
    val license: LicenseSyncInfo,
)

/** Tells the Clinic Server whether its installed license is still the current one. */
data class LicenseSyncInfo(
    val currentLicenseId: UUID?,
    val installedLicenseStatus: InstalledLicenseStatus,
)

enum class InstalledLicenseStatus {
    /** Installed license is the clinic's current license. */
    CURRENT,

    /** A renewal exists; download it from [DeviceApi.LICENSE_PATH]. */
    SUPERSEDED,

    /** Revoked by the vendor. */
    REVOKED,

    /** Not known to the vendor for this clinic. */
    UNKNOWN,

    /** The device reported no installed license. */
    NONE,
}
